+void OutputChangesTest::testObservedBrightness_data()
+{
+    QTest::addColumn<bool>("internal");
+    QTest::addColumn<double>("expectedBrightness");
+
+    QTest::addRow("external") << false << 0.7;
+    // internal displays never go to a hardware brightness of 0
+    QTest::addRow("internal") << true << 69 / 99.0;
+}
+
+void OutputChangesTest::testObservedBrightness()
+{
+    // This test verifies that brightness changes observed by a brightness device after it was set up,
+    // like ones made with the buttons of a monitor, are applied to its output
+    QFETCH(bool, internal);
+    QFETCH(double, expectedBrightness);
+
+    const QByteArray edid = readEdid(QFINDTESTDATA("data/same serial number/edid.bin"));
+    Test::setOutputConfig({
+        Test::OutputInfo{
+            .geometry = Rect(0, 0, 1280, 1024),
+            .internal = internal,
+            .edid = edid,
+        },
+    });
+    BackendOutput *output = kwinApp()->outputBackend()->outputs().front();
+
+    auto connection = Test::Connection::setup(Test::AdditionalWaylandInterface::ExternalBrightnessV1);
+    QVERIFY(connection->externalBrightness);
+    Test::ExternalBrightnessDeviceV1 device(connection->externalBrightness->create_brightness_control());
+    device.set_internal(internal ? 1 : 0);
+    device.set_edid(QString::fromLatin1(edid.toBase64()));
+    device.set_uses_ddc_ci(internal ? 0 : 1);
+    device.set_max_brightness(100);
+    device.set_observed_brightness(50);
+    device.commit();
+    QVERIFY(connection->sync());
+    QVERIFY(output->brightnessDevice());
+
+    device.set_observed_brightness(70);
+    device.commit();
+    QVERIFY(connection->sync());
+    QCOMPARE(output->brightnessSetting(), expectedBrightness);
+}
