+void Workspace::applyObservedBrightness(BrightnessDevice *device)
+{
+    const auto outputs = kwinApp()->outputBackend()->outputs();
+    const auto it = std::ranges::find(outputs, device, &BackendOutput::brightnessDevice);
+    const std::optional<double> brightness = device->observedBrightness();
+    if (it == outputs.end() || (*it)->highDynamicRange() || !brightness) {
+        return;
+    }
+    // undo the artificial HDR headroom and dimming that DrmOutput::updateBrightness applies to the hardware brightness
+    constexpr double minLuminance = 0.04;
+    double setting = (*brightness + minLuminance) / (*it)->artificialHdrHeadroom() - minLuminance;
+    if (!device->usesDdcCi() && (*it)->currentDimming() > 0) {
+        setting /= (*it)->currentDimming();
+    }
+    setting = std::clamp(setting, 0.0, 1.0);
+    OutputConfiguration cfg;
+    const auto changeset = cfg.changeSet(*it);
+    changeset->brightness = setting;
+    changeset->currentHardwareBrightness = setting;
+    const auto result = applyOutputConfiguration(cfg);
+    if (!result) {
+        qCWarning(KWIN_CORE, "Applying observed brightness of %s failed: %s", qPrintable((*it)->name()), qPrintable(result.error().message));
+    }
+}
